/**
 * Embedded 1.5s 16kHz mono PCM16 audio fixture (~48KB uncompressed) from LibriSpeech
 * utterance (speech.wav) used for diagnostic STT tests without external network or files (PA-81).
 */
export const TEST_UTTERANCE_PCM16_BASE64 = '';

let cachedBuffer: Buffer | null = null;

export function getTestUtterancePcm16(): Buffer {
  if (!cachedBuffer) {
    cachedBuffer = Buffer.from(TEST_UTTERANCE_PCM16_BASE64, 'base64');
  }
  return cachedBuffer;
}
